#include <stddef.h>

typedef float float_vec __attribute__((__vector_size__(16)));

void vectorized_s211(int iterations, int LEN_1D, float *a, float *b, float *c, float *d, float *e) {
    for (int nl = 0; nl < iterations; nl++) {
        if (LEN_1D < 3) {
            continue;
        }

        int last_scalar = LEN_1D - 2;
        int i = 1;

        // Handle first iteration separately to break loop-carried dependence
        a[i] = b[i - 1] + c[i] * d[i];
        b[i] = b[i + 1] - e[i] * d[i];
        i++;

        // Vector loop: process complete 4-element chunks, ensuring safe read of b[i+4]
        int vec_end = i + ((LEN_1D - 5 - i + 1) / 4) * 4;
        for (; i < vec_end; i += 4) {
            float_vec vb_prev = {b[i-1], b[i], b[i+1], b[i+2]};
            float_vec vc = {c[i], c[i+1], c[i+2], c[i+3]};
            float_vec vd = {d[i], d[i+1], d[i+2], d[i+3]};
            float_vec ve = {e[i], e[i+1], e[i+2], e[i+3]};
            float_vec vb_next = {b[i+1], b[i+2], b[i+3], b[i+4]};

            float_vec va = vb_prev + vc * vd;
            a[i] = va[0];
            a[i+1] = va[1];
            a[i+2] = va[2];
            a[i+3] = va[3];

            float_vec vb_new = vb_next - ve * vd;
            b[i] = vb_new[0];
            b[i+1] = vb_new[1];
            b[i+2] = vb_new[2];
            b[i+3] = vb_new[3];
        }

        // Scalar cleanup for remaining elements
        for (; i <= last_scalar; i++) {
            a[i] = b[i - 1] + c[i] * d[i];
            b[i] = b[i + 1] - e[i] * d[i];
        }
    }
}

void s211_opt(int iterations, int LEN_1D, float*a, float*b,float*c,float*d,float*e)
{
    for (int nl = 0; nl < iterations; nl++) {
        // Store original b[i+1] values needed for b[i] computation
        float* orig_b_next = (float*)malloc((LEN_1D - 1) * sizeof(float));
        for (int i = 1; i < LEN_1D - 1; i++) {
            orig_b_next[i] = b[i + 1];
        }

        // First compute b[i] using original b[i+1]
        for (int i = 1; i < LEN_1D - 1; i++) {
            b[i] = orig_b_next[i] - e[i] * d[i];
        }

        // Then compute a[i] using the updated b[i-1]
        for (int i = 1; i < LEN_1D - 1; i++) {
            a[i] = b[i - 1] + c[i] * d[i];
        }

        free(orig_b_next);
    }
}
